def transform(grid):
    a=[r[:] for r in grid]
    h,w=len(a),len(a[0])
    # Three-color seed at top: left marker, center axis color, right ray color.
    # Extend marker's color across its row and axis color along its column;
    # extend rightmost color along its row toward matching marker.
    cells=[(r,c,a[r][c]) for r in range(h) for c in range(w) if a[r][c]]
    bycolor={}
    for r,c,v in cells: bycolor.setdefault(v,[]).append((r,c))
    seed=next((c for c in cells if c[0]==0),None)
    if seed:
        r,c,v=seed
        # middle of contiguous top row triad is vertical beam; left color horizontal beam
        top=sorted((x,y,z) for x,y,z in cells if x==0)
        if len(top)>=3:
            _,leftcol,left=top[0]; _,midcol,mid=top[1]; _,rightcol,right=top[2]
            for rr in range(h):
                if a[rr][midcol]==0: a[rr][midcol]=mid
            for cc in range(w):
                if a[leftcol][cc]==0: a[leftcol][cc]=left
            # right color projects along row of its matching isolated endpoint
            endpoints=bycolor.get(right,[])
            target=next(((rr,cc) for rr,cc in endpoints if rr!=0 and cc not in (leftcol,midcol,rightcol)),None)
            if target:
                rr,cc=target
                for x in range(cc,w):
                    if a[rr][x]==0: a[rr][x]=right
    return a
